void nvfs_wr_header (NVFS_Header * const nvfs_header)
{
  nvfs_crc_calc_header (nvfs_header) ;

  if (!nvram_wr (nvfs_vars.nvram.beg , nvfs_header , sizeof *nvfs_header))
    {
      NvfsThrow NVFS_ERROR ;
    }
}

